import sys
import heapq

def compress_desc(arr):
    arr.sort(reverse=True)
    vals = []
    cnts = []
    for x in arr:
        if vals and vals[-1] == x:
            cnts[-1] += 1
        else:
            vals.append(x)
            cnts.append(1)
    return vals, cnts

def main():
    # Fast I/O reading all input at once
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, K = data[0], data[1]

    A = data[2 : 2 + N]
    B = data[2 + N : 2 + 2 * N]
    C = data[2 + 2 * N : 2 + 3 * N]

    # Compress arrays to group identical values and sort descending
    A, ca = compress_desc(A)
    B, cb = compress_desc(B)
    C, cc = compress_desc(C)

    na, nb, nc = len(A), len(B), len(C)
    base_i = nb * nc

    # Initialize max-heap with the largest possible element combination
    a0, b0, c0 = A[0], B[0], C[0]
    heap = [(-(a0 * b0 + b0 * c0 + c0 * a0), 0)]

    while heap:
        neg_v, code = heapq.heappop(heap)

        # Decode state (i, j, k)
        i, rem = divmod(code, base_i)
        j, k = divmod(rem, nc)

        # Decrease K by the number of times this specific value occurs
        K -= ca[i] * cb[j] * cc[k]
        if K <= 0:
            print(-neg_v)
            return

        a, b, c = A[i], B[j], C[k]

        # Monotonic tree generation without duplication
        if k + 1 < nc:
            c2 = C[k + 1]
            heapq.heappush(heap, (-(a * b + c2 * (a + b)), code + 1))

        if k == 0 and j + 1 < nb:
            b2 = B[j + 1]
            heapq.heappush(heap, (-(c * a + b2 * (c + a)), code + nc))

        if j == 0 and k == 0 and i + 1 < na:
            a2 = A[i + 1]
            heapq.heappush(heap, (-(b * c + a2 * (b + c)), code + base_i))

if __name__ == "__main__":
    main()
